// Types only, from MerchFlow Charts lib/parse/tracker.ts: the parser itself
// needs xlsx libraries the tracker does not ship. Generated by
// scripts/sync-merch-flow-report.mjs.
import type { Product, Show } from '../report/types';

export type TrackerData = {
  artist: string;
  tourDates: string;
  products: Product[];
  shows: Show[];
  /**
   * 0 when the tracker's `Product Ratios!G6` still reads "Enter Here", which is
   * the normal state — attendance is filled in by hand at chart time. The
   * wizard collects it rather than failing the parse.
   */
  attendance: number;
};
